using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using MediaBrowser.MediaEncoding.Encoder;

public class EncoderValidatorTests
{
    [Fact]
    public void CheckFilterWithOption_LogsWarning_WhenFilterAndOptionAreNotAvailable()
    {
        // Arrange
        var loggerMock = new Mock<ILogger>();
        var encoderValidator = new EncoderValidator(loggerMock.Object, "fakeEncoderPath");

        // Act
        var result = encoderValidator.CheckFilterWithOption("nonExistentFilter", "nonExistentOption");

        // Assert
        loggerMock.Verify(
            logger => logger.Log(
                LogLevel.Warning,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Filter: nonExistentFilter with option nonExistentOption is not available")),
                It.IsAny<Exception>(),
                It.Is<Func<It.IsAnyType, Exception, string>>((v, t) => true)),
            Times.Once);
        Assert.False(result);
    }
}
```

